<template>
<div class="result-page"><div class="toolbar"><a-button @click="router.push('/')">← 返回首页</a-button><a-button @click="historyOpen=true">🗂️ 历史行程</a-button><a-button v-if="itinerary?.trip_id" type="primary" :loading="saving" @click="save">💾 保存行程</a-button><a-button v-if="itinerary?.trip_id" @click="startSession">💬 开启会话编辑</a-button><a-button v-if="itinerary?.trip_id" @click="downloadMarkdown">⬇️ Markdown</a-button></div>
<a-alert v-if="!itinerary" type="info" message="暂无行程" description="请先从首页生成旅行计划" show-icon/><template v-else><div class="layout"><aside class="nav"><h3>行程导航</h3><a-menu mode="inline" :selected-keys="[activeSection]" @click="scrollTo"><a-menu-item key="overview">行程概览</a-menu-item><a-menu-item key="budget">预算明细</a-menu-item><a-menu-item key="map">景点地图</a-menu-item><a-menu-item key="weather">天气信息</a-menu-item><a-menu-item key="edit">智能调整</a-menu-item><a-menu-item key="places">地点图片</a-menu-item><a-menu-item key="days">每日行程</a-menu-item></a-menu></aside><main class="main"><div class="twocol"><a-card id="overview" title="行程概览" :bordered="false"><h2>{{ itinerary.destination }}旅行计划</h2><p>{{ itinerary.start_date }} 至 {{ itinerary.end_date }} · 当前版本 {{ itinerary.version ?? '未保存' }}</p><p>{{ itinerary.summary }}</p></a-card><a-card id="budget" title="预算明细" :bordered="false"><div class="budget-grid"><div>活动费用<strong>¥{{ activityTotal }}</strong></div><div>餐饮费用<strong>¥{{ mealTotal }}</strong></div><div>路线费用<strong>¥{{ routeTotal }}</strong></div><div>其他预算<strong>¥{{ otherTotal }}</strong></div></div><div class="total">预计总费用 <b>¥{{ itinerary.total_estimated_cost }}</b></div></a-card></div><div class="twocol"><a-card id="map" title="📍 景点地图" :bordered="false"><div ref="mapEl" class="map"><span v-if="mapStatus">{{ mapStatus }}</span></div></a-card><a-card id="weather" title="🌤️ 天气信息" :bordered="false"><div v-for="day in itinerary.days" :key="day.date" class="weather-row"><div><b>{{ day.date }}</b><small>{{ day.title }}</small></div><strong v-if="day.weather?.status==='available'">{{ day.weather.low_celsius ?? '-' }}° / {{ day.weather.high_celsius ?? '-' }}°</strong><span v-else>天气未知</span><small class="wide">{{ weatherText(day) }}</small></div></a-card></div><a-card id="edit" title="🪄 智能调整行程" :bordered="false"><div class="edit-form"><a-select v-model:value="editDate" :options="dateOptions" placeholder="选择日期"/><a-textarea v-model:value="instruction" :rows="2" placeholder="例如：减少当天活动，保留傍晚散步"/><a-button type="primary" :loading="editing" @click="submitEdit">智能调整</a-button></div><a-alert v-if="changeSummary.length" type="success" :message="changeSummary.join('；')"/></a-card><a-card id="places" title="🖼️ 地点图片" :bordered="false"><div class="places"><article v-for="(item,i) in placeActivities" :key="item.name+i"><img :src="placeImage(i)" :alt="item.name" @error="imageFallback"/><h3>{{ item.name }}</h3><p>📍 {{ item.location || item.address || '行程地点' }}</p><p>{{ item.description }}</p></article></div></a-card><a-card id="days" title="📅 每日行程" :bordered="false"><a-collapse v-model:activeKey="activeDays" accordion><a-collapse-panel v-for="day in itinerary.days" :key="day.date"><template #header><b>{{ day.title }}</b><span class="date">{{ day.date }}</span></template><a-alert v-if="day.weather" :type="day.weather.status==='available'?'info':'warning'" :message="weatherText(day)" :description="day.weather_advice.join('；') || undefined"/><div v-for="item in day.activities" :key="item.time+item.name" class="activity"><time>{{ item.time }}</time><div><h3>{{ item.name }}</h3><p>{{ item.description }}</p><p v-if="item.location || item.address">📍 {{ item.location || item.address }}</p><small>费用：¥{{ item.estimated_cost }}<span v-if="item.route_from_previous"> · {{ routeText(item.route_from_previous) }}</span></small></div></div><a-button type="dashed" block @click="editDate=day.date;scrollTo({key:'edit'})">✏️ 修改这一天</a-button></a-collapse-panel></a-collapse></a-card></main></div></template><a-drawer v-model:open="historyOpen" title="历史行程"><a-list :data-source="history"><template #renderItem="{item}"><a-list-item><a-list-item-meta :title="item.destination" :description="`${item.start_date} 至 ${item.end_date}`"/><a-button size="small" @click="openTrip(item.trip_id)">打开</a-button></a-list-item></template></a-list></a-drawer></div>
</template>
<script setup lang="ts">
import { computed,nextTick,onMounted,ref,watch } from 'vue';import {useRouter} from 'vue-router';import {message} from 'ant-design-vue';import AMapLoader from '@amap/amap-jsapi-loader';import {createSession,editSession,exportTrip,getTrip,listTrips,saveTrip} from '@/services/api';import {normalizeItinerary,type Activity,type DayPlan,type Itinerary,type TripSession,type TripSummary} from '@/types'
const router=useRouter();const itinerary=ref<Itinerary|null>(null);const activeSection=ref('overview');const activeDays=ref<string[]>([]);const historyOpen=ref(false);const history=ref<TripSummary[]>([]);const saving=ref(false);const editing=ref(false);const editDate=ref('');const instruction=ref('');const changeSummary=ref<string[]>([]);const session=ref<TripSession|null>(null);const mapEl=ref<HTMLElement>();const mapStatus=ref('');let map:any=null
const dateOptions=computed(()=>itinerary.value?.days.map(d=>({label:d.date,value:d.date}))||[]);const placeActivities=computed(()=>itinerary.value?.days.flatMap(d=>d.activities).filter(a=>{if(a.poi_category==='meal'||a.poi_category==='hotel')return false;const text=`${a.name} ${a.description||''} ${a.location||''} ${a.address||''}`;return !/酒店|宾馆|旅馆|民宿|客栈|住宿|入住|餐厅|饭店|酒楼|酒家|大牌档|大排档|档口|餐饮|用餐|就餐|早餐|午餐|晚餐|夜宵|小吃|简餐|美食|菜品|吃饭|品尝|餐食|食客|restaurant|hotel|宿泊|dining|meal|food/i.test(text)})||[]);const activityTotal=computed(()=>placeActivities.value.reduce((n,a)=>n+a.estimated_cost,0));const mealTotal=computed(()=>itinerary.value?.days.flatMap(d=>d.activities).filter(a=>a.poi_category==='meal'||/餐|饭|小吃|大牌档|大排档|简餐|美食|用餐|就餐/.test(`${a.name} ${a.description||''}`)).reduce((n,a)=>n+a.estimated_cost,0)||0);const routeTotal=computed(()=>placeActivities.value.reduce((n,a)=>n+(a.route_from_previous?Math.round(a.route_from_previous.distance_meters/1000):0),0));const otherTotal=computed(()=>Math.max(0,(itinerary.value?.total_estimated_cost||0)-activityTotal.value));
onMounted(async()=>{const raw=sessionStorage.getItem('itinerary');if(raw){itinerary.value=normalizeItinerary(JSON.parse(raw));activeDays.value=itinerary.value.days[0]?[itinerary.value.days[0].date]:[];await nextTick();initMap()}});watch(historyOpen,async open=>{if(open)history.value=(await listTrips()).items});function weatherText(d:DayPlan){if(!d.weather)return'暂无天气数据';if(d.weather.status==='unknown')return'天气未知（超出预报范围）';return`${d.weather.condition||'天气可用'} · ${d.weather.low_celsius??'-'}°C 至 ${d.weather.high_celsius??'-'}°C`};function routeText(r:NonNullable<Activity['route_from_previous']>){return`${r.mode==='walking'?'步行':'驾车'} ${Math.round(r.distance_meters/100)/10}km · ${Math.round(r.duration_seconds/60)}分钟`};function scrollTo({key}:{key:string}){activeSection.value=key;document.getElementById(key)?.scrollIntoView({behavior:'smooth'})};const images=['https://images.unsplash.com/photo-1528127269322-539801943592?auto=format&fit=crop&w=800&q=80','https://images.unsplash.com/photo-1470004914212-05527e49370b?auto=format&fit=crop&w=800&q=80','https://images.unsplash.com/photo-1500534623283-312aade485b7?auto=format&fit=crop&w=800&q=80'];function placeImage(i:number){return images[i%images.length]};function imageFallback(e:Event){(e.target as HTMLImageElement).src=images[0]};async function save(){if(!itinerary.value)return;saving.value=true;try{itinerary.value=normalizeItinerary(await saveTrip(itinerary.value,itinerary.value.version));sessionStorage.setItem('itinerary',JSON.stringify(itinerary.value));message.success('行程已保存')}catch(e){message.error(e instanceof Error?e.message:'保存失败')}finally{saving.value=false}};async function openTrip(id:string){try{itinerary.value=normalizeItinerary(await getTrip(id));sessionStorage.setItem('itinerary',JSON.stringify(itinerary.value));historyOpen.value=false;await nextTick();initMap()}catch(e){message.error(e instanceof Error?e.message:'打开失败')}};async function startSession(){if(!itinerary.value?.trip_id||!itinerary.value.version)return;try{session.value=await createSession(itinerary.value.trip_id,itinerary.value.version);message.success('会话已开启')}catch(e){message.error(e instanceof Error?e.message:'会话开启失败')}};async function submitEdit(){if(!itinerary.value?.trip_id||!editDate.value||!instruction.value.trim())return message.error('请选择日期并填写修改要求');if(!session.value)await startSession();if(!session.value)return;editing.value=true;try{const r=await editSession(itinerary.value.trip_id,session.value.session_id,editDate.value,instruction.value);itinerary.value=normalizeItinerary(r.itinerary);session.value=r.session;changeSummary.value=r.change_summary;sessionStorage.setItem('itinerary',JSON.stringify(itinerary.value));instruction.value='';message.success('会话编辑已完成')}catch(e){message.error(e instanceof Error?e.message:'编辑失败')}finally{editing.value=false}};async function downloadMarkdown(){if(!itinerary.value?.trip_id||!itinerary.value.version)return;try{const b=await exportTrip(itinerary.value.trip_id,itinerary.value.version,'markdown');const u=URL.createObjectURL(b);const a=document.createElement('a');a.href=u;a.download=`${itinerary.value.destination}-行程.md`;a.click();URL.revokeObjectURL(u)}catch(e){message.error(e instanceof Error?e.message:'导出失败')}};async function initMap(){if(!mapEl.value||!itinerary.value)return;const p=itinerary.value.days.flatMap(d=>d.activities).filter(a=>a.latitude!==null&&a.longitude!==null);if(!p.length){mapStatus.value='当前行程没有可定位的地点';return}if(!import.meta.env.VITE_AMAP_WEB_JS_KEY||!import.meta.env.VITE_AMAP_SECURITY_JS_CODE){mapStatus.value='请配置高德地图 Key';return}try{(window as any)._AMapSecurityConfig={securityJsCode:import.meta.env.VITE_AMAP_SECURITY_JS_CODE};const A=await AMapLoader.load({key:import.meta.env.VITE_AMAP_WEB_JS_KEY,version:'2.0',plugins:['AMap.Marker']});map=new A.Map(mapEl.value,{zoom:11,center:[p[0].longitude,p[0].latitude]});const ms=p.map((a,i)=>new A.Marker({position:[a.longitude,a.latitude],title:a.name,label:{content:`${i+1}`}}));map.add(ms);map.setFitView(ms)}catch{mapStatus.value='高德地图加载失败'}}
</script>
<style scoped>
.result-page{max-width:1280px;margin:auto}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px}.layout{display:grid;grid-template-columns:205px 1fr;gap:18px}.nav{height:max-content;position:sticky;top:18px;background:#fff;border:1px solid #e8eaf2;border-radius:10px;overflow:hidden}.nav h3{color:#fff;background:linear-gradient(90deg,#667eea,#764ba2);margin:0;padding:12px 15px}.nav :deep(.ant-menu){border:0}.main{display:flex;flex-direction:column;gap:18px;min-width:0}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:18px}.budget-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.budget-grid div{background:#f7f8fd;padding:12px;border-radius:8px;color:#7d8797}.budget-grid strong{display:block;color:#3977e8;font-size:18px;margin-top:5px}.total{margin-top:14px;background:linear-gradient(90deg,#667eea,#764ba2);padding:12px;color:#fff;border-radius:8px;display:flex;justify-content:space-between}.total b{font-size:20px}.map{height:300px;background:#eef3fb;display:flex;align-items:center;justify-content:center;color:#7d8797}.weather-row{display:grid;grid-template-columns:1fr auto;gap:4px;border-bottom:1px solid #edf0f5;padding:10px 0}.weather-row div{display:flex;flex-direction:column}.weather-row small{color:#8992a5}.weather-row .wide{grid-column:1/-1}.weather-row strong{color:#3977e8}.edit-form{display:grid;grid-template-columns:180px 1fr 120px;gap:10px}.places{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.places article{border:1px solid #edf0f5;border-radius:8px;overflow:hidden}.places img{width:100%;height:140px;object-fit:cover}.places h3,.places p{margin:8px 12px}.places p{font-size:13px;color:#606b7d}.date{float:right;color:#8992a5}.activity{display:flex;gap:14px;padding:14px 6px;border-bottom:1px solid #edf0f5}.activity time{color:#3977e8;font-weight:700;width:50px}.activity h3{margin:0 0 5px}.activity p{margin:5px 0;color:#606b7d}.activity small{color:#8992a5}@media(max-width:850px){.layout{display:block}.nav{display:none}.twocol{grid-template-columns:1fr}.edit-form{grid-template-columns:1fr}.places{grid-template-columns:1fr 1fr}}@media(max-width:520px){.places{grid-template-columns:1fr}}
</style>
